import pandas as pd
import numpy as np

# Load trip data and adjacency data
df = pd.read_csv("chunks_csv/cyclehire_w005.csv")
adj = pd.read_csv(ADJACENCY_PATH)

# Compute self-containment ratios per borough
departures = df.groupby('StartBorough').size().reset_index(name='departures')
self_contained = df[df['StartBorough'] == df['EndBorough']].groupby('StartBorough').size().reset_index(name='self_contained')
ratios = pd.merge(departures, self_contained, on='StartBorough', how='left').fillna(0)
ratios['ratio'] = ratios['self_contained'] / ratios['departures']
ratio_series = ratios.set_index('StartBorough')['ratio']

# Build neighbor dictionary from adjacency list
all_boroughs = set(ratios['StartBorough'])
neighbors_dict = {b: [] for b in all_boroughs}
for _, row in adj.iterrows():
    b1, b2 = row['borough'], row['neighbor']
    if b1 in all_boroughs and b2 in all_boroughs:
        neighbors_dict[b1].append(b2)
        neighbors_dict[b2].append(b1)

# Compute neighbor averages
neighbor_avg = {}
for borough in all_boroughs:
    n_list = neighbors_dict[borough]
    if n_list:
        neighbor_avg[borough] = ratio_series[n_list].mean()
    else:
        neighbor_avg[borough] = np.nan

# Permutation test for neighbor averages (500 permutations)
n_perm = 500
count_high = {b: 0 for b in all_boroughs}
count_low = {b: 0 for b in all_boroughs}
observed_avg = pd.Series(neighbor_avg)

for _ in range(n_perm):
    perm_ratios = ratio_series.sample(frac=1).values  # Shuffle values
    perm_series = pd.Series(perm_ratios, index=ratio_series.index)
    perm_avg = {}
    for b in all_boroughs:
        n_list = neighbors_dict[b]
        if n_list:
            perm_avg[b] = perm_series[n_list].mean()
        else:
            perm_avg[b] = np.nan
    perm_series_avg = pd.Series(perm_avg)

    for b in all_boroughs:
        if not np.isnan(observed_avg[b]):
            if perm_series_avg[b] >= observed_avg[b]:
                count_high[b] += 1
            if perm_series_avg[b] <= observed_avg[b]:
                count_low[b] += 1

# Compute p-values (with +1 to avoid p=0)
p_high = {b: (count_high[b] + 1) / (n_perm + 1) for b in all_boroughs}
p_low = {b: (count_low[b] + 1) / (n_perm + 1) for b in all_boroughs}

# Identify hotspots and coldspots
global_median = ratio_series.median()
hotspots = []
coldspots = []

for b in all_boroughs:
    if np.isnan(neighbor_avg[b]):  # Skip boroughs without neighbors
        continue
    if ratio_series[b] > global_median and neighbor_avg[b] > global_median and p_high[b] < 0.05:
        hotspots.append(b)
    elif ratio_series[b] < global_median and neighbor_avg[b] < global_median and p_low[b] < 0.05:
        coldspots.append(b)

# Print reasoning
print("Self-Containment Ratios:")
for b in all_boroughs:
    print(f"{b}: {ratio_series[b]:.4f}")

print("\nNeighbor Averages:")
for b in all_boroughs:
    if not np.isnan(neighbor_avg[b]):
        print(f"{b}: {neighbor_avg[b]:.4f}")

print("\nHotspots (high ratio, high neighbor avg, significant p_high):")
for b in hotspots:
    print(f"{b}: ratio={ratio_series[b]:.4f}, neighbor_avg={neighbor_avg[b]:.4f}, p_high={p_high[b]:.4f}")

print("\nColdspots (low ratio, low neighbor avg, significant p_low):")
for b in coldspots:
    print(f"{b}: ratio={ratio_series[b]:.4f}, neighbor_avg={neighbor_avg[b]:.4f}, p_low={p_low[b]:.4f}")

# Prepare final answer
final_entries = []
for b in hotspots:
    final_entries.append(f"{b} (HH, p={p_high[b]:.4f})")
for b in coldspots:
    final_entries.append(f"{b} (LL, p={p_low[b]:.4f})")

if not final_entries:
    print("FINAL ANSWER: none")
else:
    print("FINAL ANSWER: " + ", ".join(final_entries))
